fn count_evens(limit: i32) -> i32 {
    let mut count = 0;
    for n in 0..limit {
        if n % 2 == 0 {
            count += 1;
        }
    }
    count
}

fn linear_search(nums: &[i32], target: i32) -> Option<usize> {
    for (i, &n) in nums.iter().enumerate() {
        if n == target {
            return Some(i);
        }
    }
    None
}

fn binary_search(nums: &[i32], target: i32) -> Option<usize> {
    let mut lo = 0;
    let mut hi = nums.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if nums[mid] == target {
            return Some(mid);
        } else if nums[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
}

fn bubble_sort(nums: &mut [i32]) {
    let len = nums.len();
    for i in 0..len {
        for j in 0..len - i - 1 {
            if nums[j] > nums[j + 1] {
                nums.swap(j, j + 1);
            }
        }
    }
}

fn selection_sort(nums: &mut [i32]) {
    let len = nums.len();
    for i in 0..len {
        let mut min = i;
        for j in i + 1..len {
            if nums[j] < nums[min] {
                min = j;
            }
        }
        nums.swap(i, min);
    }
}

fn insertion_sort(nums: &mut [i32]) {
    for i in 1..nums.len() {
        let key = nums[i];
        let mut j = i;
        while j > 0 && nums[j - 1] > key {
            nums[j] = nums[j - 1];
            j -= 1;
        }
        nums[j] = key;
    }
}

fn merge_sort(nums: &[i32]) -> Vec<i32> {
    if nums.len() <= 1 {
        return nums.to_vec();
    }
    let mid = nums.len() / 2;
    let left = merge_sort(&nums[..mid]);
    let right = merge_sort(&nums[mid..]);
    merge(&left, &right)
}

fn merge(left: &[i32], right: &[i32]) -> Vec<i32> {
    let mut result = Vec::with_capacity(left.len() + right.len());
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i] <= right[j] {
            result.push(left[i]);
            i += 1;
        } else {
            result.push(right[j]);
            j += 1;
        }
    }
    result.extend_from_slice(&left[i..]);
    result.extend_from_slice(&right[j..]);
    result
}

fn quick_sort(nums: &mut [i32]) {
    let len = nums.len();
    if len > 1 {
        let p = partition(nums);
        let (left, right) = nums.split_at_mut(p);
        quick_sort(left);
        quick_sort(&mut right[1..]);
    }
}

fn partition(nums: &mut [i32]) -> usize {
    let high = nums.len() - 1;
    let pivot = nums[high];
    let mut i = 0;
    for j in 0..high {
        if nums[j] < pivot {
            nums.swap(i, j);
            i += 1;
        }
    }
    nums.swap(i, high);
    i
}

fn heap_sort(nums: &mut [i32]) {
    let n = nums.len();
    for i in (0..n / 2).rev() {
        sift_down(nums, i, n);
    }
    for i in (1..n).rev() {
        nums.swap(0, i);
        sift_down(nums, 0, i);
    }
}

fn sift_down(nums: &mut [i32], root: usize, size: usize) {
    let mut root = root;
    loop {
        let mut largest = root;
        let left = 2 * root + 1;
        let right = 2 * root + 2;
        if left < size && nums[left] > nums[largest] {
            largest = left;
        }
        if right < size && nums[right] > nums[largest] {
            largest = right;
        }
        if largest == root {
            return;
        }
        nums.swap(root, largest);
        root = largest;
    }
}

struct Graph {
    edges: HashMap<String, Vec<String>>,
}

impl Graph {
    fn new() -> Self {
        Graph {
            edges: HashMap::new(),
        }
    }

    fn add_edge(&mut self, from: &str, to: &str) {
        self.edges
            .entry(from.to_string())
            .or_default()
            .push(to.to_string());
        self.edges
            .entry(to.to_string())
            .or_default()
            .push(from.to_string());
    }
}

fn bfs(graph: &Graph, start: &str) -> Vec<String> {
    let mut visited: HashMap<String, bool> = HashMap::new();
    visited.insert(start.to_string(), true);
    let mut queue = VecDeque::new();
    queue.push_back(start.to_string());
    let mut order = Vec::new();

    while let Some(node) = queue.pop_front() {
        order.push(node.clone());
        if let Some(neighbors) = graph.edges.get(&node) {
            for neighbor in neighbors {
                if !visited.contains_key(neighbor) {
                    visited.insert(neighbor.clone(), true);
                    queue.push_back(neighbor.clone());
                }
            }
        }
    }
    order
}

fn dfs(graph: &Graph, start: &str) -> Vec<String> {
    let mut visited = HashSet::new();
    let mut order = Vec::new();
    dfs_visit(graph, start, &mut visited, &mut order);
    order
}

fn dfs_visit(graph: &Graph, node: &str, visited: &mut HashSet<String>, order: &mut Vec<String>) {
    if visited.contains(node) {
        return;
    }
    visited.insert(node.to_string());
    order.push(node.to_string());
    if let Some(neighbors) = graph.edges.get(node) {
        for neighbor in neighbors {
            dfs_visit(graph, neighbor, visited, order);
        }
    }
}

struct Edge {
    to: String,
    weight: i32,
}

struct WeightedGraph {
    edges: HashMap<String, Vec<Edge>>,
}

impl WeightedGraph {
    fn add_edge(&mut self, from: &str, to: &str, weight: i32) {
        self.edges.entry(from.to_string()).or_default().push(Edge {
            to: to.to_string(),
            weight,
        });
        self.edges.entry(to.to_string()).or_default().push(Edge {
            to: from.to_string(),
            weight,
        });
    }
}

fn dijkstra(graph: &WeightedGraph, start: &str, nodes: &[String]) -> HashMap<String, i32> {
    let mut dist: HashMap<String, i32> = nodes.iter().map(|n| (n.clone(), i32::MAX)).collect();
    let mut visited: HashMap<String, bool> = HashMap::new();
    dist.insert(start.to_string(), 0);

    while visited.len() < nodes.len() {
        let current = match closest_unvisited(&dist, &visited) {
            Some(node) => node,
            None => break,
        };
        visited.insert(current.clone(), true);
        if let Some(edges) = graph.edges.get(&current) {
            for edge in edges {
                let new_dist = dist[&current] + edge.weight;
                if new_dist < dist[&edge.to] {
                    dist.insert(edge.to.clone(), new_dist);
                }
            }
        }
    }
    dist
}

fn closest_unvisited(
    dist: &HashMap<String, i32>,
    visited: &HashMap<String, bool>,
) -> Option<String> {
    let mut best: Option<String> = None;
    let mut best_dist = i32::MAX;
    for (node, &d) in dist {
        if !visited.contains_key(node) && d < best_dist {
            best = Some(node.clone());
            best_dist = d;
        }
    }
    best
}
